				["args"]  = new JArray(args)
			};

			var str    = payload.ToString(Formatting.None);
			var buffer = Encoding.UTF8.GetBytes(str);



		}
	}
}

using System;
using System.Net;
using System.Net.Sockets;
using System.Text;
using Cysharp.Threading.Tasks;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Nox.CCK.Utils;
using Nox.SDK.Control;

namespace api.nox.control {
	public class Client : IClient {
		private readonly Server _server;
		private TcpClient _client;
		private NetworkStream _stream;

		internal Client(TcpClient client, Server server) {
			_client = client;
			_server = server;
			_stream = _client.GetStream();
		}

		public EndPoint GetEndPoint() => _client?.Client?.RemoteEndPoint;

		public bool IsConnected() => _client is { Connected: true };

		public async UniTask Close() {
			if (!IsConnected()) return;

			try {
				_stream?.Close();
				_client?.Close();
				_client = null;
				_stream = null;
				await UniTask.Yield();
			} catch (Exception ex) {
				Logger.LogError($"Error closing connection to client {GetEndPoint()}: {ex.Message}");
			}
		}

		public IServer GetServer() => _server;

		public async UniTask Send(string ev, params object[] args) {
			if (!IsConnected()) return;

			try {
				var payload = new JObject {
					["event"] = ev,
					["args"] = new JArray(args)
				};

				var str = payload.ToString(Formatting.None);
				var buffer = Encoding.UTF8.GetBytes(str + "\n");

				await _stream.WriteAsync(buffer, 0, buffer.Length);
			} catch (Exception ex) {
				Logger.LogError($"Error sending data to client {GetEndPoint()}: {ex.Message}");
			}
		}
	}
}

using Nox.CCK.Mods.Cores;
using Nox.CCK.Mods.Initializers;

namespace api.nox.websocket {
	public class Main : IMainModInitializer {
		public void OnInitializeMain(MainModCoreAPI api) { }

		public void OnDisposeMain() { }
	}
}

using Nox.CCK.Mods.Cores;
using Nox.CCK.Mods.Initializers;
using UnityEngine;

namespace api.nox.websocket {
	public class Main : IMainModInitializer {
		private WebSocketServerManager _serverManager;

		public void OnInitializeMain(MainModCoreAPI api) {
			// Create WebSocket server manager
			var serverObject = new GameObject("WebSocketServerManager");
			_serverManager = serverObject.AddComponent<WebSocketServerManager>();
			Object.DontDestroyOnLoad(serverObject);

			// Subscribe to events
			_serverManager.OnClientConnected += OnClientConnected;
			_serverManager.OnClientDisconnected += OnClientDisconnected;
			_serverManager.OnMessageReceived += OnMessageReceived;

			Debug.Log("WebSocket module initialized");
		}

		private void OnClientConnected(WebSocketClient client) {
			Debug.Log($"[WebSocket] Client connected: {client.Id} from {client.RemoteEndpoint}");
		}

		private void OnClientDisconnected(WebSocketClient client) {
			Debug.Log($"[WebSocket] Client disconnected: {client.Id}");
		}

		private void OnMessageReceived(WebSocketClient client, string message) {
			Debug.Log($"[WebSocket] Message from {client.Id}: {message}");
		}

		public void OnDisposeMain() {
			if (_serverManager != null) {
				_serverManager.OnClientConnected -= OnClientConnected;
				_serverManager.OnClientDisconnected -= OnClientDisconnected;
				_serverManager.OnMessageReceived -= OnMessageReceived;

				_serverManager.StopServer();
				Object.Destroy(_serverManager.gameObject);
			}

			Debug.Log("WebSocket module disposed");
		}
	}
}

using System;

namespace api.nox.websocket {
	/// <summary>
	/// Message types for WebSocket communication
	/// </summary>
	public enum MessageType {
		Text,
		Binary,
		Ping,
		Pong,
		Close
	}

	/// <summary>
	/// WebSocket message data
	/// </summary>
	public class WebSocketMessage {
		public MessageType Type { get; set; }
		public string TextData { get; set; }
		public byte[] BinaryData { get; set; }
		public WebSocketClient Sender { get; set; }
		public DateTime Timestamp { get; set; }

		public WebSocketMessage() {
			Timestamp = DateTime.UtcNow;
		}

		public static WebSocketMessage CreateTextMessage(string text, WebSocketClient sender = null) {
			return new WebSocketMessage {
				Type = MessageType.Text,
				TextData = text,
				Sender = sender
			};
		}

		public static WebSocketMessage CreateBinaryMessage(byte[] data, WebSocketClient sender = null) {
			return new WebSocketMessage {
				Type = MessageType.Binary,
				BinaryData = data,
				Sender = sender
			};
		}
	}
}
